import pytest
from shop.orders import OrderService
class FakeRepo: # a fake: real behaviour, stored in a dict
def __init__(self):
self.rows = {}
def add(self, order):
self.rows[order["id"]] = order
def get(self, order_id):
return self.rows[order_id]
@pytest.fixture
def service():
return OrderService(repo=FakeRepo(), mailer=Mock())
def test_place_stores_order(service):
service.place("A-1", "ada@example.com", 108)
assert service.repo.get("A-1")["total"] == 108 # state verification
def test_place_sends_confirmation(service):
service.place("A-1", "ada@example.com", 108)
service.mailer.send.assert_called_once_with( # behaviour verification
"ada@example.com", "Order A-1 confirmed"
)
Fowler calls these two styles state verification (check the result) and behaviour verification (check the calls). Prefer state: behaviour checks break when you refactor how the work is done, even if the result is still right. Use a mock when the call is the result, as with sending an e-mail.
Common pitfall: Mock() accepts any attribute, so mailer.sned(...) (a typo) passes silently. Use create_autospec(RealMailer) so the mock has the same methods and signatures as the real class.

